function pipelineRecordStatus(review){return ['accepted','legacy_imported'].includes(review?.pipelineRecordStatus)?review.pipelineRecordStatus:null;}
function skillRecordLabel(item){const status=pipelineRecordStatus(item.skillReview);return status==='accepted'?'已接受分析':status==='legacy_imported'?'历史分析迁移':'技能复核记录';}
function skillRecordCaveat(review){const status=pipelineRecordStatus(review);return status==='accepted'?'已通过协议和来源校验；核读属于提交者声明，程序未独立执行 AI。':status==='legacy_imported'?'历史分析迁移保留原记录，不代表本次重新采集、重新核读或补齐缺失证据。':'';}
function pipelineScopeText(p){const meta=p?.pipelineIntegration;if(meta?.schemaVersion!=='vps-pipeline-catalog/1')return null;const count=v=>Number.isSafeInteger(v)&&v>=0?String(v):'未知';return `已载入 ${state.posts.length} 篇原帖、${state.items.length} 条对象；包含 v5 基础目录 ${count(meta.baselinePosts)} 篇、${count(meta.baselineObjects)} 条对象。流水线已接受 ${count(meta.acceptedPosts)} 篇分析、迁移 ${count(meta.legacyImportedPosts)} 篇历史分析（可能与基础目录重合，不相加）。历史迁移不表示重新核读，缺失字段保留未知。`;}
function skillCurrencyBasis(f){if(f.status!=='inferred')return '来源明确币种';const note=f.note||'',cur=f.value?.currency;if(cur==='USD'&&/默认/.test(note))return '默认美元（来源未写币种）';if(cur==='USD'&&/刀/.test(note))return '刀按项目约定识别为美元';if(cur==='EUR')return '按来源及项目约定识别为欧元';return '报价含推断，见字段依据';}
/* Staged adapter for actual, finalized vps-analysis/1 public projections. No synthetic data. */
const SKILL_STATUS_LABELS={reported:'来源明示',computed:'计算结果',inferred:'推断',official_current:'官网当前资料',unknown:'未知',conflict:'来源冲突'};
function skillFacts(item){return item.skillReview?.fieldObservations||[];}
function skillFact(item,id){return skillFacts(item).find(f=>f.skillFieldId===id);}
function skillHistoricalFact(item,id){const f=skillFact(item,id);return f&&f.filterEligible&&['reported','computed'].includes(f.status)?f:null;}
function skillFieldValues(item,key){const rows=skillFacts(item).filter(f=>f.fieldKey===key&&f.filterEligible);const values=[];for(const f of rows){const v=f.value;if(v==null)continue;
 if(f.skillFieldId==='disk_type'){const type=normalizeDiskType(v);if(type)values.push(type);}
 else if(f.skillFieldId.startsWith('hardware_')){const keys=new Set(state.items.flatMap(i=>skillFacts(i).filter(x=>x.fieldKey===key&&x.filterEligible).map(x=>x.comparisonKey)));if(keys.size===1&&f.comparisonKey)values.push(v);}
 else if(f.skillFieldId==='ip_usage_location'){for(const [family,location]of Object.entries(v))if(location?.country)values.push(`${family.toUpperCase().replace('IPV','IPv')} · ${location.country}${location.continent?' / '+location.continent:''}`);}
 else if(f.skillFieldId==='ip_registered_location'){for(const [family,location]of Object.entries(v))if(location)values.push(`${family.toUpperCase().replace('IPV','IPv')} · ${location}`);}
 else if(['asn','ip_organization'].includes(f.skillFieldId)){for(const [family,value]of Object.entries(v))if(value!=null)values.push(value);}
 else if(f.skillFieldId==='memory_overcommit'){for(const [mechanism,result]of Object.entries(v))if(result!=null)values.push(`${mechanism==='balloon'?'气球回收':'KSM复用'}${result==='detected'?'已检测到':result==='not_detected'?'未检测到':result}`);}
 else if(f.skillFieldId==='country_region'){if(v.country)values.push(v.country);}
 else if(f.skillFieldId==='port_bandwidth_mbps'){if(typeof f.normalizedValue==='number')values.push(f.normalizedValue);}
 else if(typeof v==='string'||typeof v==='number')values.push(v);
 }
 return [...new Set(values)];
}
function applySkillRefresh(payload){if(payload.schemaVersion!=='nodeseek-skill-refresh/1'||payload.publicProjection!==true)throw new Error('Unsupported public skill projection');const byId=new Map(state.items.map(i=>[i.itemId,i]));for(const row of payload.entries||[]){const item=byId.get(row.itemId);if(!item||String(item.postId)!==String(row.postId)||item.sourceUrl!==row.sourceUrl)throw new Error('Skill refresh item identity mismatch');item.skillReview=row;
 if(pipelineRecordStatus(row)==='accepted'){item.cpuBenchmarks=[];item.priceObservations=[];item.price={raw:null};item.bandwidthClaims=[];item.trafficQuota={value:null,unit:null,period:null,direction:null};item.network.claimedRouteTags=[];item.configuration={vcpu:null,cpuModel:null,memoryValue:null,memoryUnit:null,diskValue:null,diskUnit:null,basis:'当前已接受分析；历史值在记录详情中保留。'};item.vendor=null;item.location={country:null,city:null,region:null};}
 const post=state.posts.find(p=>p.postId===row.postId);if(post&&post.items.length===1&&row.summary)post.summary=row.summary;
 const period=skillFact(item,'billing_period'),monthly=skillFact(item,'monthly_price');
 if(monthly?.filterEligible&&monthly?.value?.amount!=null){item.priceObservations=[{id:`${item.itemId}-fresh-monthly-quote`,amount:null,currency:monthly.value.currency,billingPeriod:period?.value||null,monthlyQuote:monthly.value.amount,priceKind:'unknown',raw:item.price?.raw||'来源月均报价',currencyBasis:skillCurrencyBasis(monthly),status:monthly.status,filterEligible:true,isPrimary:true,note:monthly.note}];}
 else if(monthly&&(!monthly.filterEligible||['unknown','conflict'].includes(monthly.status))){item.priceObservations=[];}
 const timed=skillFact(item,'test_time');if(timed){item.testedAt={primary:{raw:null,timezone:null,beijing:null,status:timed.status},reports:(row.confirmedReportTimes||[]).map(t=>({raw:t.raw,timezone:'由本次来源确认',beijing:t.beijing})),datesBeijing:[...new Set((row.confirmedReportTimes||[]).map(t=>t.beijing.slice(0,10)))],dateUncertain:!(row.confirmedReportTimes||[]).length};}
 if(post&&post.items.length===1){post.warnings=[`${skillRecordCaveat(row)||'记录来自指定技能的实际素材复核。'}采集状态${row.captureStatus}；未取得的原图不视为已读。`,...['test_time','country_region','city','billing_period'].map(id=>skillFact(item,id)).filter(f=>f&&['unknown','conflict'].includes(f.status)).map(f=>f.note).filter(Boolean)];}
 const core={vcpu:['vcpu',null],cpu_model:['cpuModel',null],memory_gb:['memoryValue','memoryUnit'],disk_gb:['diskValue','diskUnit']};
 for(const [fid,[valueKey,unitKey]]of Object.entries(core)){const f=skillFact(item,fid);if(!f)continue;if(pipelineRecordStatus(row)==='accepted'&&f.rawDisplay&&unitKey){item.configuration[valueKey]=f.rawDisplay.value;item.configuration[unitKey]=f.rawDisplay.unit;}if(['unknown','conflict'].includes(f.status)){item.configuration[valueKey]=null;if(unitKey)item.configuration[unitKey]=null;continue;}if(f.filterEligible&&['reported','computed'].includes(f.status)){item.configuration[valueKey]=f.value;if(unitKey)item.configuration[unitKey]=f.unit;item.configuration.basis='本次指定技能复核的来源事实；原单位与状态见61字段详情。';}}
 const vendor=skillHistoricalFact(item,'provider');if(vendor)item.vendor=vendor.value;
 if(['unknown','conflict'].includes(skillFact(item,'country_region')?.status)){item.location.country=null;item.location.region=null;}if(['unknown','conflict'].includes(skillFact(item,'city')?.status))item.location.city=null;
 const country=skillHistoricalFact(item,'country_region'),city=skillHistoricalFact(item,'city');if(country?.value?.country)item.location.country=country.value.country;if(country?.value?.region)item.location.region=country.value.region;if(city)item.location.city=city.value;
 if(country||city){item.location.basis='本次技能分析有明确部署地点证据；IP数据库地点另列。';item.location.note='不以使用地、注册地或默认坐标替代机房证据。';}
 if(row.summary)item.summary=row.summary;
 if(skillFact(item,'routes_from_server')||skillFact(item,'routes_to_server')){const routes=skillRouteRows(item);item.network.routeObservations=routes.map(r=>({family:r.family,direction:r.direction==='return'?'回程':'去程',operator:r.operator,label:r.labels.join(' / '),basis:r.basis,evidenceType:'measured_script_label'}));item.network.reportedRouteTags=[...new Set(routes.flatMap(r=>r.labels))];item.network.filterRouteTags=[...new Set([...item.network.reportedRouteTags,...(item.network.claimedRouteTags||[])])];}
 // Only version-pinned scores from the new report replace the same tool/metric's old observations.
 for(const b of row.cpuBenchmarks||[]){if(!b.comparisonEligible)continue;item.cpuBenchmarks=(item.cpuBenchmarks||[]).filter(old=>!(old.tool===b.tool&&old.metric===b.metric&&String(old.majorVersion)===String(b.majorVersion)));item.cpuBenchmarks.push({...b,id:`${item.itemId}-skill-${b.majorVersion}-${b.metric}`,isPrimary:true,comparisonKey:`geekbench:${b.majorVersion}:${b.metric}`,phase:'本次复核的原始报告',sourcePostURL:item.sourceUrl,evidenceKind:'skill_reviewed_source',evidence:'来源文件与哈希见本次61字段复核详情。'});}
 }
 state.skillRefresh=payload;
}
function skillRouteRows(item){return (item.skillReview?.routeObservations||[]).filter(r=>r.filterEligible).map(r=>({family:r.family,direction:r.direction,operator:r.operator,transport:r.transport||null,targetCity:r.targetCity||null,labels:r.reportedLabels.map(canonicalRoute),basis:'本次指定技能复核来源'}));}
function skillReportTimes(item){return(item.skillReview?.confirmedReportTimes||[]).map(t=>t.beijing);}
function skillMonthlyRecords(item){const f=skillFact(item,'monthly_price'),period=skillFact(item,'billing_period');if(!f||!f.filterEligible||f.value?.amount==null||!f.value.currency)return[];return[{amount:null,monthlyQuote:f.value.amount,currency:f.value.currency,billingPeriod:period?.value||null,monthly:f.value.amount,priceKind:'unknown',filterEligible:true,isPrimary:true,sourcePostURL:item.sourceUrl,raw:'月均报价；实际周期与原始金额见61字段详情',currencyBasis:skillCurrencyBasis(f),status:f.status,monthlyAlreadyNormalized:true}];}
function skillValueHtml(value){if(value==null)return '<span class="unknown">未知</span>';if(typeof value!=='object')return escapeHTML(value);if(Array.isArray(value))return value.map(skillValueHtml).join('<br>');const names={ipv4:'IPv4',ipv6:'IPv6',telecom:'电信',unicom:'联通',mobile:'移动',mean_ms:'均值 ms',sample_count:'有效样本',method:'统计方法',amount:'月均金额',currency:'币种',country:'国家',continent:'洲',region:'区域',report_times:'已确认报告时间',timezone_basis:'时区依据',half_hour_buckets:'北京时间半小时桶',balloon:'气球回收',ksm:'KSM',very_low:'极低风险',low:'低风险',medium:'中风险',high:'高风险',very_high:'极高风险',suspicious:'可疑',usage_counts:'使用类型数量',company_counts:'公司类型数量'};return Object.entries(value).map(([key,v])=>`<div class="skill-value-row"><span>${escapeHTML(names[key]||key)}</span><div>${skillValueHtml(v)}</div></div>`).join('');}
function skillReviewDetails(item){const review=item.skillReview;if(!review)return '';const facts=review.fieldObservations||[],known=facts.filter(f=>f.value!==null).length;const rows=facts.map(f=>`<tr><td>${escapeHTML(f.label)}<small>${escapeHTML(f.skillFieldId)}</small></td><td><span class="skill-status status-${escapeHTML(f.status)}">${escapeHTML(SKILL_STATUS_LABELS[f.status]||f.status)}</span>${skillValueHtml(f.value)}${f.unit?`<small>${escapeHTML(f.unit)}</small>`:''}${f.benchmarkContext?.reportedToolLabel?`<small>来源工具：${escapeHTML(f.benchmarkContext.reportedToolLabel)}</small>`:''}</td><td>${escapeHTML(f.note||'')}${(f.evidenceRefs||[]).map(e=>`<small>${escapeHTML(e.sourceKind)} · ${escapeHTML(e.assetId)}${e.sha256?' · '+escapeHTML(e.sha256.slice(0,12)):''}<br>${escapeHTML(e.locator||'')}</small>`).join('')}</td></tr>`).join('');return `<section class="detail-section skill-review"><h3>${escapeHTML(skillRecordLabel(item))} · 完整61字段</h3>${skillRecordCaveat(review)?`<p class="detail-note">${escapeHTML(skillRecordCaveat(review))}</p>`:''}<p class="detail-note">${known} 项有值；其余保持未知或冲突。采集状态：${review.captureStatus==='ready'?'素材齐备':'部分素材缺失'}，缺失记录 ${review.missingAssetCount??'未知'} 项。复核时间 ${escapeHTML(review.analyzedAt||'未标注')}，不等于原始测试时间。</p>${review.sourceMedia?`<p class="detail-note">${pipelineRecordStatus(review)==='legacy_imported'?'原分析记录阅读':pipelineRecordStatus(review)==='accepted'?'提交记录声明阅读':'实际阅读'} ${review.sourceMedia.imagesReviewed} 个图片文件、${review.sourceMedia.textSourcesReviewed} 个文本来源；图片计数含报告图及其他素材，已读不代表所有字段都有证据。</p>`:''}${review.pipelineLegacyLinks?.length?'<p class="detail-note">已关联历史迁移记录；此处保留原目录较完整的事实，迁移没有新增核读声明。</p>':''}<p class="detail-note">官网当前资料与推断分别标注；未混入历史实测。只公开结构化事实和来源定位，不公开首帖全文、原图、作者或IP地址。</p><details><summary>查看全部字段、状态与依据</summary><table class="route-table"><thead><tr><th>字段</th><th>值 / 状态</th><th>说明 / 证据定位</th></tr></thead><tbody>${rows}</tbody></table></details>${skillRouteDetails(item)}${review.reviewHistory?.length?`<details><summary>保留的历史分析（${review.reviewHistory.length} 条）</summary>${review.reviewHistory.map(previous=>skillReviewDetails({...item,skillReview:previous})).join('')}</details>`:''}</section>`;}

function refreshScopeBanner(){const p=state.skillRefresh;if(!p)return;const reviewed=new Set(p.entries.map(e=>e.postId)).size,b=p.currentBatch;const el=document.getElementById('refresh-scope');const pipelineText=pipelineScopeText(p);if(pipelineText){if(el)el.textContent=pipelineText;return;}if(el)el.textContent=b?`本批新增 ${b.newPosts} 篇原帖、${b.newObjects} 条对象；当前 ${state.posts.length} 篇原帖中累计 ${reviewed} 篇有指定技能复核。本批素材齐备 ${b.captureStatuses.ready||0} 篇、部分缺失 ${b.captureStatuses.partial||0} 篇。保留历史快照；采集时间不等于测试时间。`:`本次使用指定技能复核 ${reviewed} / ${state.posts.length} 篇原帖；其余沿用历史快照。原图未获取的记录保留部分完成，采集时间不等于测试时间。`;}

function skillCapacityThresholdsMatch(item,filters){for(const[id,key]of [['vcpu','cpu'],['memory_gb','memory'],['disk_gb','disk']]){if(filters[key]===''||filters[key]==null)continue;const fact=skillFact(item,id);if(fact&&!fact.filterEligible)return false;}return true;}
function skillCapacityNote(item){const pairs=[['memory_gb','内存'],['disk_gb','硬盘']];return pairs.filter(([id])=>{const f=skillFact(item,id);return f&&f.status==='inferred'&&!f.filterEligible}).map(([,label])=>label+'原始容量保留；标准单位换算存疑，不参与该阈值').join('；');}
function skillRouteDetails(item){const rows=item.skillReview?.routeObservations||[];if(!rows.some(r=>r.transport))return '';return `<details><summary>逐目标 / 传输协议线路记录（${rows.length} 条）</summary><table class="route-table"><thead><tr><th>协议 / 目标 / 运营商</th><th>路径标签</th><th>范围与来源</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${escapeHTML(r.family)} · ${escapeHTML(r.targetCity||'目标未注明')} · ${escapeHTML(r.transport||'传输协议未注明')}<br>${escapeHTML(r.operator)} / ${r.direction==='outbound'?'去程':r.direction==='return'?'回程':'方向未知'}</td><td>${escapeHTML(r.rawLabel)}<small>${r.filterEligible?'仅此观测可匹配标签':'此路径无可用结果，不进正向筛选'}</small></td><td>${r.partialCoverage?'上游或部分结果未知；不扩大成全路径结论。':'此城市 / 传输协议观测，不保证其他条件。'}${(r.evidenceRefs||[]).map(e=>`<small>${escapeHTML(e.locator)} · ${escapeHTML(e.sha256?.slice(0,12)||'')}</small>`).join('')}</td></tr>`).join('')}</tbody></table></details>`;}
